/**
 * Builds the ingestion fixtures with pure-JS writers (docx, ExcelJS, PptxGenJS), so they can be
 * regenerated on any OS and CI needs nothing installed. Run:
 *   node node_modules/tsx/dist/cli.mjs test/fixtures/files/make-fixtures.ts
 */

import { writeFileSync } from "node:fs";
import { join } from "node:path";
import {
	AlignmentType,
	BorderStyle,
	Document,
	ExternalHyperlink,
	Footer,
	FootnoteReferenceRun,
	Header,
	HeadingLevel,
	ImageRun,
	LevelFormat,
	Packer,
	PageNumber,
	Paragraph,
	ShadingType,
	Table,
	TableCell,
	TableRow,
	TextRun,
	WidthType,
} from "docx";
import ExcelJS from "exceljs";
import PptxGenJS from "pptxgenjs";
import { encodePng } from "../../../src/files/parse/png.ts";

const here = import.meta.dirname;

/** A violet pill on a light card: obviously an image, small enough to keep fixtures tiny. */
function mark(): Buffer {
	const width = 240;
	const height = 90;
	const px = new Uint8Array(width * height * 3);
	for (let y = 0; y < height; y++) {
		for (let x = 0; x < width; x++) {
			const i = (y * width + x) * 3;
			const inPill = x > 12 && x < width - 12 && y > 18 && y < height - 18 && Math.min(x - 12, width - 12 - x) + Math.min(y - 18, height - 18 - y) > 14;
			if (inPill) {
				px[i] = 124;
				px[i + 1] = 58;
				px[i + 2] = 237;
			} else {
				px[i] = 243;
				px[i + 1] = 239;
				px[i + 2] = 228;
			}
		}
	}
	// a white dot inside the pill
	for (let y = 33; y < 57; y++) for (let x = 30; x < 54; x++) if ((x - 42) ** 2 + (y - 45) ** 2 < 100) px.fill(255, (y * width + x) * 3, (y * width + x) * 3 + 3);
	return encodePng(width, height, "rgb", px);
}

const PNG = mark();

/** The slice of the PptxGenJS API this generator uses (its typings are inconsistent under NodeNext). */
interface FixturePptx {
	layout: string;
	author: string;
	title: string;
	theme: { headFontFace?: string; bodyFontFace?: string; lang?: string };
	ChartType: { bar: string };
	addSlide(): {
		background: { color: string };
		addText(text: unknown, opts: Record<string, unknown>): void;
		addNotes(text: string): void;
		addTable(rows: unknown[][], opts: Record<string, unknown>): void;
		addChart(type: string, data: unknown[], opts: Record<string, unknown>): void;
		addImage(opts: Record<string, unknown>): void;
	};
	writeFile(opts: { fileName: string }): Promise<void>;
}



// ---------------------------------------------------------------- docx

async function makeDocx() {
	const cell = (text: string, opts: { bold?: boolean; shade?: string } = {}) =>
		new TableCell({
			shading: opts.shade ? { type: ShadingType.CLEAR, fill: opts.shade, color: "auto" } : undefined,
			margins: { top: 60, bottom: 60, left: 100, right: 100 },
			children: [new Paragraph({ children: [new TextRun({ text, bold: opts.bold, font: "Georgia", size: 20 })] })],
		});

	const doc = new Document({
		title: "Outpost ingestion fixture",
		description: "Generated by make-fixtures.ts",
		creator: "fixture generator",
		styles: {
			default: {
				document: { run: { font: "Georgia", size: 22, color: "1f1b2e" } },
			},
			characterStyles: [{ id: "Hyperlink", name: "Hyperlink", run: { color: "7C3AED", underline: {} } }],
			paragraphStyles: [
				{
					id: "Heading1",
					name: "Heading 1",
					basedOn: "Normal",
					next: "Normal",
					quickFormat: true,
					run: { font: "Georgia", size: 40, bold: true, color: "7C3AED" },
					paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 0 },
				},
				{
					id: "Heading2",
					name: "Heading 2",
					basedOn: "Normal",
					next: "Normal",
					quickFormat: true,
					run: { font: "Georgia", size: 28, bold: true, color: "5B21B6" },
					paragraph: { spacing: { before: 200, after: 100 }, outlineLevel: 1 },
				},
			],
		},
		numbering: {
			config: [
				{
					reference: "ordered",
					levels: [
						{
							level: 0,
							format: LevelFormat.DECIMAL,
							text: "%1.",
							alignment: AlignmentType.START,
							style: { paragraph: { indent: { left: 720, hanging: 360 } } },
						},
					],
				},
			],
		},
		footnotes: {
			1: { children: [new Paragraph({ children: [new TextRun({ text: "Source: fixture generator.", size: 18 })] })] },
		},
		sections: [
			{
				properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1134, right: 1134, bottom: 1134, left: 1134 } } },
				headers: { default: new Header({ children: [new Paragraph({ children: [new TextRun({ text: "Outpost - internal", size: 18, color: "6b6480" })] })] }) },
				footers: {
					default: new Footer({
						children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: "Page ", size: 18 }), new TextRun({ children: [PageNumber.CURRENT], size: 18 })] })],
					}),
				},
				children: [
					new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun("Outpost ingestion fixture")] }),
					new Paragraph({
						children: [
							new TextRun({ text: "Bold violet lead-in. ", bold: true, color: "7C3AED" }),
							new TextRun({ text: "Italic note. ", italics: true }),
							new TextRun({ text: "Plain text with a " }),
							new ExternalHyperlink({ link: "https://example.com/outpost", children: [new TextRun({ text: "link", style: "Hyperlink" })] }),
							new TextRun({ text: " and a footnote" }),
							new FootnoteReferenceRun(1),
							new TextRun({ text: "." }),
						],
					}),
					new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun("Lists")] }),
					new Paragraph({ text: "First bullet", bullet: { level: 0 } }),
					new Paragraph({ text: "Second bullet", bullet: { level: 0 } }),
					new Paragraph({ text: "Numbered one", numbering: { reference: "ordered", level: 0 } }),
					new Paragraph({ text: "Numbered two", numbering: { reference: "ordered", level: 0 } }),
					new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun("Table")] }),
					new Table({
						width: { size: 100, type: WidthType.PERCENTAGE },
						borders: {
							top: { style: BorderStyle.SINGLE, size: 4, color: "d8d2c4" },
							bottom: { style: BorderStyle.SINGLE, size: 4, color: "d8d2c4" },
							left: { style: BorderStyle.SINGLE, size: 4, color: "d8d2c4" },
							right: { style: BorderStyle.SINGLE, size: 4, color: "d8d2c4" },
							insideHorizontal: { style: BorderStyle.SINGLE, size: 4, color: "d8d2c4" },
							insideVertical: { style: BorderStyle.SINGLE, size: 4, color: "d8d2c4" },
						},
						rows: [
							new TableRow({
								tableHeader: true,
								children: [cell("Service", { bold: true, shade: "EDE9FE" }), cell("Owner", { bold: true, shade: "EDE9FE" }), cell("Status", { bold: true, shade: "EDE9FE" })],
							}),
							new TableRow({ children: [cell("Portal"), cell("Alice"), cell("Live")] }),
							new TableRow({ children: [cell("Ingest"), cell("Bob"), cell("Draft")] }),
						],
					}),
					new Paragraph({ children: [new TextRun({ text: "Diagram", bold: true, size: 20 })] }),
					new Paragraph({ alignment: AlignmentType.CENTER, children: [new ImageRun({ type: "png", data: PNG, transformation: { width: 240, height: 90 } })] }),
				],
			},
		],
	});

	writeFileSync(join(here, "sample.docx"), await Packer.toBuffer(doc));
}

// ---------------------------------------------------------------- xlsx

async function makeXlsx() {
	const wb = new ExcelJS.Workbook();
	wb.creator = "fixture generator";
	wb.created = new Date("2026-10-20T09:00:00Z");

	const ws = wb.addWorksheet("Services", { properties: { defaultRowHeight: 18 } });
	ws.columns = [
		{ header: "Service", key: "service", width: 22 },
		{ header: "Owner", key: "owner", width: 14 },
		{ header: "Criticality", key: "crit", width: 12 },
		{ header: "Advisories", key: "adv", width: 12 },
		{ header: "Updated", key: "updated", width: 14 },
		{ header: "Cost", key: "cost", width: 14 },
	];
	ws.getRow(1).eachCell((c) => {
		c.font = { bold: true, name: "Georgia", color: { argb: "FF3B2E6B" } };
		c.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFEDE9FE" } };
		c.border = { bottom: { style: "thin", color: { argb: "FFD8D2C4" } } };
	});
	ws.addRow({ service: "Portal", owner: "Alice", crit: "high", adv: 12, updated: new Date("2026-10-01T00:00:00Z"), cost: 1250.5 });
	ws.addRow({ service: "Ingest", owner: "Bob", crit: "medium", adv: 3, updated: new Date("2026-10-12T00:00:00Z"), cost: 890 });
	ws.addRow({ service: "Scheduler", owner: "Chen", crit: "low", adv: 0, updated: new Date("2026-09-20T00:00:00Z"), cost: 410.25 });
	for (const row of [2, 3, 4]) {
		ws.getCell(`E${row}`).numFmt = "yyyy-mm-dd";
		ws.getCell(`F${row}`).numFmt = '"$"#,##0.00';
	}
	ws.getCell("A5").value = "Total";
	ws.getCell("A5").font = { bold: true };
	ws.getCell("D5").value = { formula: "SUM(D2:D4)", result: 15 };
	ws.getCell("F5").value = { formula: "SUM(F2:F4)", result: 2550.75 };
	ws.getCell("F5").numFmt = '"$"#,##0.00';
	ws.mergeCells("A7:C7");
	ws.getCell("A7").value = "Merged note across three columns";
	ws.getCell("A7").alignment = { horizontal: "center" };
	ws.autoFilter = "A1:F1";
	ws.views = [{ state: "frozen", ySplit: 1 }];

	const notes = wb.addWorksheet("Notes");
	notes.getCell("A1").value = "Sources";
	notes.getCell("A1").font = { bold: true, italic: true };
	notes.getCell("A2").value = "service inventory export";
	notes.getCell("A3").value = "2026-10-20";
	notes.getCell("B2").value = 42;
	notes.getCell("B3").value = true;

	const hidden = wb.addWorksheet("Hidden", { state: "hidden" });
	hidden.getCell("A1").value = "internal only";

	notes.addImage(wb.addImage({ base64: PNG.toString("base64"), extension: "png" }), "B5");

	writeFileSync(join(here, "sample.xlsx"), Buffer.from(await wb.xlsx.writeBuffer()));
}

// ---------------------------------------------------------------- pptx

async function makePptx() {
	const ppt = new (PptxGenJS as unknown as new () => FixturePptx)();
	ppt.layout = "LAYOUT_16x9";
	ppt.author = "fixture generator";
	ppt.title = "Outpost ingestion fixture";
	ppt.theme = { headFontFace: "Georgia", bodyFontFace: "Georgia", lang: "en-US" };

	const s1 = ppt.addSlide();
	s1.background = { color: "F3EFE4" };
	s1.addText("Ingestion fixture", { x: 0.6, y: 0.5, w: 8, h: 0.9, fontFace: "Georgia", fontSize: 40, bold: true, color: "7C3AED" });
	s1.addText("Themes, fonts and shapes survive the round trip.", { x: 0.6, y: 1.5, w: 8, h: 0.6, fontFace: "Georgia", fontSize: 18, color: "1F1B2E" });
	s1.addNotes("Speaker note for slide one.");

	const s2 = ppt.addSlide();
	s2.addText("What we keep", { x: 0.6, y: 0.4, w: 8, h: 0.7, fontFace: "Georgia", fontSize: 30, bold: true, color: "5B21B6" });
	s2.addText(
		[
			{ text: "Theme fonts and colours", options: { bullet: true, fontSize: 20, color: "1F1B2E" } },
			{ text: "Structure and order", options: { bullet: true, fontSize: 20, color: "1F1B2E" } },
			{ text: "Tables, charts, images", options: { bullet: true, fontSize: 20, color: "1F1B2E", italic: true } },
		],
		{ x: 0.7, y: 1.3, w: 8, h: 2.4, fontFace: "Georgia" },
	);

	const s3 = ppt.addSlide();
	s3.addText("Advisories by service", { x: 0.6, y: 0.4, w: 8, h: 0.7, fontFace: "Georgia", fontSize: 30, bold: true, color: "5B21B6" });
	s3.addTable(
		[
			[
				{ text: "Service", options: { bold: true, fill: { color: "EDE9FE" } } },
				{ text: "Owner", options: { bold: true, fill: { color: "EDE9FE" } } },
				{ text: "Count", options: { bold: true, fill: { color: "EDE9FE" } } },
			],
			["Portal", "Alice", "12"],
			["Ingest", "Bob", "3"],
		],
		{ x: 0.6, y: 1.4, w: 6, colW: [2.4, 2, 1.6], border: { pt: 1, color: "D8D2C4" }, fontFace: "Georgia", fontSize: 14 },
	);

	const s4 = ppt.addSlide();
	s4.addText("Trend", { x: 0.6, y: 0.4, w: 8, h: 0.7, fontFace: "Georgia", fontSize: 30, bold: true, color: "5B21B6" });
	s4.addChart(
		ppt.ChartType.bar,
		[
			{ name: "Advisories", labels: ["Jan", "Feb", "Mar"], values: [4, 9, 6] },
		],
		{ x: 0.6, y: 1.3, w: 5.4, h: 3, barDir: "col", chartColors: ["7C3AED"], showValue: true },
	);
	s4.addImage({ data: `image/png;base64,${PNG.toString("base64")}`, x: 6.6, y: 1.4, w: 2.4, h: 0.9 });

	await ppt.writeFile({ fileName: join(here, "sample.pptx") });
}

await makeDocx();
await makeXlsx();
await makePptx();
console.log("fixtures written");
